#include "stellar/semantic_declarations.h"
#include <cmath>
#include <set>
#include <stdexcept>

namespace stellar::v0_1 {
const Token& SemanticDeclarationParser::peek(std::size_t n) const { return tokens_.at(std::min(at_+n,tokens_.size()-1)); }
Token SemanticDeclarationParser::take() { return tokens_.at(at_++); }
[[noreturn]] void SemanticDeclarationParser::fail(std::string code,std::string message,Span span,std::string help) { error_={std::move(code),"error",std::move(message),file_,span,std::move(help)}; throw std::runtime_error("parse"); }
Token SemanticDeclarationParser::identifier(const char* help) { if(peek().kind!=TokenKind::identifier) fail("S1008","expected identifier",peek().span,help); return take(); }
Token SemanticDeclarationParser::expect(TokenKind kind,const char* message) { if(peek().kind!=kind) fail("S1009",message,peek().span,"follow the v0.1 typed grammar"); return take(); }
long long SemanticDeclarationParser::integer_literal(const std::string& code,const char* help) { if(peek().kind!=TokenKind::number||peek().value.find('.')!=std::string::npos) fail(code,"expected integer literal",peek().span,help); try{return std::stoll(take().value);}catch(...){fail(code,"integer literal is out of range",peek().span,help);} }

ElementDecl SemanticDeclarationParser::element() { const auto start=take().span.start; const auto name=identifier("declare an element name"); expect(TokenKind::angular,"expected '/' before element kind"); const auto kind=identifier("declare an element kind"); ElementDecl d{name.value,kind.value}; expect(TokenKind::left_crescent,"expected '(' after element kind"); if(peek().kind!=TokenKind::right_crescent) for(;;){const auto key=identifier("declare an element metadata key"); expect(TokenKind::colon,"expected ':' after element metadata key"); if(peek().kind!=TokenKind::number&&peek().kind!=TokenKind::string_value&&peek().kind!=TokenKind::identifier) fail("S1010","expected an element metadata value",peek().span,"use a bounded number, string, or identifier value"); d.metadata.emplace_back(key.value,take().value); if(peek().kind!=TokenKind::comma) break; take();} expect(TokenKind::right_crescent,"expected ')' after element metadata"); const auto end=expect(TokenKind::dot,"expected '·' after element"); d.span={start,end.span.end}; return d; }
OrbDecl SemanticDeclarationParser::orb() { const auto start=take().span.start; const auto name=identifier("declare an orb name"); expect(TokenKind::angular,"expected '/' before orb kind"); const auto kind=identifier("declare an orb kind"); OrbDecl d{name.value,kind.value}; expect(TokenKind::left_crescent,"expected '(' after orb kind"); if(peek().kind==TokenKind::right_crescent) fail("S3001","orb must contain at least one element",peek().span,"list one or more declared element names"); for(;;){d.elements.push_back(identifier("reference a declared element inside the orb").value); if(peek().kind!=TokenKind::comma) break; take(); if(peek().kind==TokenKind::right_crescent) fail("S1009","expected an element after ','",peek().span,"separate element names with commas");} expect(TokenKind::right_crescent,"expected ')' after orb elements"); const auto end=expect(TokenKind::dot,"expected '·' after orb"); d.span={start,end.span.end}; return d; }
HarmonicDecl SemanticDeclarationParser::harmonic() { const auto start=take().span.start; const auto name=identifier("declare a harmonic signature name"); expect(TokenKind::angular,"expected '/' before harmonic signature kind"); const auto kind=identifier("declare a harmonic signature kind"); HarmonicDecl d{name.value,kind.value}; expect(TokenKind::left_crescent,"expected '(' after harmonic signature kind"); if(peek().kind==TokenKind::right_crescent) fail("S3001","harmonic signature requires parameters",peek().span,"use purity, drift, capture, witness, and eq metadata"); for(;;){const auto key=identifier("declare a harmonic parameter"); expect(TokenKind::colon,"expected ':' after harmonic parameter"); if(peek().kind!=TokenKind::number&&peek().kind!=TokenKind::identifier) fail("S1010","expected a numeric or boolean harmonic parameter",peek().span,"use a bounded number or true/false"); d.parameters.emplace_back(key.value,take().value); if(peek().kind!=TokenKind::comma) break; take(); if(peek().kind==TokenKind::right_crescent) fail("S1009","expected a harmonic parameter after ','",peek().span,"separate parameters with commas");} if(d.parameters.size()!=5) fail("S3001","harmonic signature requires exactly five parameters",name.span,"declare purity, drift, capture, witness, and eq"); std::set<std::string> keys; for(const auto&[key,value]:d.parameters){if(!keys.insert(key).second) fail("S2002","duplicate harmonic parameter",name.span,"use each harmonic parameter once"); if(key!="purity"&&key!="drift"&&key!="capture"&&key!="witness"&&key!="eq") fail("S3001","unknown harmonic parameter",name.span,"use purity, drift, capture, witness, or eq"); if(key=="witness"){if(value!="true"&&value!="false") fail("S3001","witness harmonic parameter must be boolean",name.span,"use true or false");} else {try{const double v=std::stod(value);if(!std::isfinite(v)||v<0||v>1) throw std::runtime_error("range");}catch(...){fail("S3001","harmonic parameter must be a finite value from 0 through 1",name.span,"use a bounded decimal value");}}} expect(TokenKind::right_crescent,"expected ')' after harmonic parameters"); const auto end=expect(TokenKind::dot,"expected '·' after harmonic signature"); d.span={start,end.span.end}; return d; }
TotemDecl SemanticDeclarationParser::totem() { const auto start=take().span.start; const auto name=identifier("declare a Totem name"); expect(TokenKind::angular,"expected '/' before Totem layer"); const auto kind=identifier("declare a Totem layer"); TotemDecl d{name.value,kind.value}; expect(TokenKind::left_crescent,"expected '(' after Totem layer"); if(peek().kind==TokenKind::right_crescent) fail("S3001","Totem requires lineage metadata",peek().span,"use parent, child, and/or shortfall references"); for(;;){const auto key=identifier("declare Totem lineage metadata"); expect(TokenKind::colon,"expected ':' after Totem lineage metadata"); const auto value=identifier("reference a Totem or Shortfall by identifier"); if(key.value=="parent"){if(!d.parent.empty()) fail("S2002","duplicate Totem parent reference",key.span,"declare one parent reference"); d.parent=value.value;} else if(key.value=="child") d.children.push_back(value.value); else if(key.value=="shortfall") d.shortfalls.push_back(value.value); else fail("S3001","unknown Totem lineage metadata",key.span,"use parent, child, or shortfall"); if(peek().kind!=TokenKind::comma) break; take(); if(peek().kind==TokenKind::right_crescent) fail("S1009","expected Totem lineage metadata after ','",peek().span,"separate references with commas");} expect(TokenKind::right_crescent,"expected ')' after Totem lineage metadata"); const auto end=expect(TokenKind::dot,"expected '·' after Totem"); d.span={start,end.span.end}; return d; }
ActuatorDecl SemanticDeclarationParser::actuator() { const auto start=take().span.start; const auto name=identifier("declare a Repair Actuator proposal name"); expect(TokenKind::angular,"expected '/' before Actuator kind"); const auto kind=identifier("declare an Actuator proposal kind"); ActuatorDecl d{name.value,kind.value}; expect(TokenKind::left_crescent,"expected '(' after Actuator kind"); if(peek().kind==TokenKind::right_crescent) fail("S3001","Actuator proposal requires target, Totem, Shortfall, and authorization metadata",peek().span,"use target, totem, shortfall, and authorization: required"); std::set<std::string> keys; for(;;){const auto key=identifier("declare Actuator proposal metadata"); expect(TokenKind::colon,"expected ':' after Actuator proposal metadata"); const auto value=identifier("use a stable target, Totem, Shortfall, or authorization identifier"); if(!keys.insert(key.value).second) fail("S2002","duplicate Actuator proposal metadata",key.span,"use each required metadata key once"); if(key.value=="target")d.target=value.value; else if(key.value=="totem")d.totem=value.value; else if(key.value=="shortfall")d.shortfall=value.value; else if(key.value=="authorization")d.authorization=value.value; else fail("S3001","unknown Actuator proposal metadata",key.span,"use target, totem, shortfall, or authorization"); if(peek().kind!=TokenKind::comma) break; take(); if(peek().kind==TokenKind::right_crescent) fail("S1009","expected Actuator proposal metadata after ','",peek().span,"separate metadata with commas");} if(d.target.empty()||d.totem.empty()||d.shortfall.empty()||d.authorization!="required") fail("S3001","Actuator proposal requires target, Totem, Shortfall, and authorization: required",name.span,"declare all four required proposal metadata values"); expect(TokenKind::right_crescent,"expected ')' after Actuator proposal metadata"); const auto end=expect(TokenKind::dot,"expected '·' after Actuator proposal"); d.span={start,end.span.end}; return d; }
GapPauseDecl SemanticDeclarationParser::gap_pause() { const auto start=take().span.start; const auto pause=identifier("declare a Gap-Pause identifier"); expect(TokenKind::angular,"expected '/' before Gap-Pause reason"); const auto reason=identifier("declare a non-empty Gap-Pause reason"); GapPauseDecl d{pause.value,reason.value}; expect(TokenKind::left_crescent,"expected '(' after Gap-Pause reason"); std::set<std::string> keys; for(;;){const auto key=identifier("declare Gap-Pause control metadata"); expect(TokenKind::colon,"expected ':' after Gap-Pause metadata"); if(!keys.insert(key.value).second) fail("S6101","duplicate Gap-Pause metadata",key.span,"use timeout_ms, resume, and abort exactly once"); if(key.value=="timeout_ms"){d.timeout_ms=integer_literal("S6103","use an integer timeout in the range 1..86400000 milliseconds"); if(d.timeout_ms<1||d.timeout_ms>86400000) fail("S6103","Gap-Pause timeout is outside 1..86400000 milliseconds",key.span,"use a bounded timeout in the ratified range");} else if(key.value=="resume"){d.resume=identifier("use authorized or manual resume").value; if(d.resume!="authorized"&&d.resume!="manual") fail("S6101","invalid Gap-Pause resume mode",key.span,"use authorized or manual");} else if(key.value=="abort"){d.abort=identifier("use explicit or timeout abort").value; if(d.abort!="explicit"&&d.abort!="timeout") fail("S6101","invalid Gap-Pause abort mode",key.span,"use explicit or timeout");} else fail("S6101","unknown Gap-Pause metadata",key.span,"use timeout_ms, resume, or abort"); if(peek().kind!=TokenKind::comma) break; take(); if(peek().kind==TokenKind::right_crescent) fail("S6101","Gap-Pause metadata is incomplete",peek().span,"declare timeout_ms, resume, and abort");} if(d.timeout_ms==0||d.resume.empty()||d.abort.empty()) fail("S6101","Gap-Pause requires timeout_ms, resume, and abort metadata",pause.span,"declare all three required control fields"); expect(TokenKind::right_crescent,"expected ')' after Gap-Pause metadata"); const auto end=expect(TokenKind::dot,"expected '·' after Gap-Pause"); d.span={start,end.span.end}; return d; }
FieldLayerDecl SemanticDeclarationParser::field() { const auto start=take().span.start; const auto name=identifier("declare a Field name"); expect(TokenKind::angular,"expected '/' before Field kind"); const auto kind=identifier("declare a Field kind"); FieldLayerDecl d{name.value,kind.value}; expect(TokenKind::left_crescent,"expected '(' after Field kind"); std::set<std::string> keys; for(;;){const auto key=identifier("declare Field metadata"); expect(TokenKind::colon,"expected ':' after Field metadata"); if(!keys.insert(key.value).second) fail("S6201","duplicate Field metadata",key.span,"use orb, target, and state exactly once"); if(key.value=="orb")d.orb=identifier("reference a declared Orb by identifier").value; else if(key.value=="target")d.target=identifier("reference a non-empty Field target identifier").value; else if(key.value=="state")d.state=identifier("use declared, active, paused, stale, or closed").value; else fail("S6201","unknown Field metadata",key.span,"use orb, target, or state"); if(peek().kind!=TokenKind::comma) break; take(); if(peek().kind==TokenKind::right_crescent) fail("S6201","Field metadata is incomplete",peek().span,"declare orb, target, and state");} if(d.orb.empty()||d.target.empty()||d.state.empty()) fail("S6201","Field requires orb, target, and state metadata",name.span,"declare all three required Field metadata values"); if(d.state!="declared"&&d.state!="active"&&d.state!="paused"&&d.state!="stale"&&d.state!="closed") fail("S6201","invalid Field state",name.span,"use declared, active, paused, stale, or closed"); expect(TokenKind::right_crescent,"expected ')' after Field metadata"); const auto end=expect(TokenKind::dot,"expected '·' after Field"); d.span={start,end.span.end}; return d; }
}
